<script lang="ts">let { options = [], value = $bindable(''), placeholder = 'Select…' }: { options: { value: string; label: string; hint?: string }[]; value?: string; placeholder?: string } = $props();let q = $state('');let open = $state(false);let filtered = $derived(options.filter((o) => !q || o.label.toLowerCase().includes(q.toLowerCase())));</script><div class="cb"><input bind:value={q} {placeholder} onfocus={() => (open = true)} role="combobox" aria-expanded={open} aria-controls="cb-list" /><div class="cur">{options.find((o) => o.value === value)?.label ?? ''}</div>{#if open}<div class="list" role="listbox" id="cb-list">{#each filtered as o}<button role="option" aria-selected={value === o.value} onclick={() => { value = o.value; open = false; q = ''; }}>{o.label}{#if o.hint}<span>{o.hint}</span>{/if}</button>{/each}</div>{/if}</div><style>.cb{position:relative}.cb input{width:100%;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius);padding:var(--space-2) var(--space-3);color:var(--text-0)}.cur{font-size:var(--fs-xs);color:var(--text-2);margin-top:2px}.list{position:absolute;z-index:20;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius);max-height:240px;overflow:auto;width:100%}.list button{display:flex;justify-content:space-between;width:100%;background:transparent;border:none;color:var(--text-0);padding:var(--space-2) var(--space-3)}.list button:hover{background:var(--bg-3)}</style>
